import { Injectable, Inject, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

type CacheEntry<T = unknown> = {
  data: T;
  savedAt: number;
  ttl?: number | null; // milliseconds
};

const TAB_CACHE_KEY = '__tab_json_cache__';

@Injectable({
  providedIn: 'root'
})
export class CacheService {
  private readonly isBrowser: boolean;
  // Fallback for SSR or restricted environments
  private memCache: Record<string, CacheEntry> = {};

  constructor(@Inject(PLATFORM_ID) platformId: Object) {
    this.isBrowser = isPlatformBrowser(platformId);
  }

  private readStore(): Record<string, CacheEntry> {
    if (!this.isBrowser) return this.memCache;
    try {
      const raw = sessionStorage.getItem(TAB_CACHE_KEY);
      return raw ? JSON.parse(raw) : {};
    } catch {
      return {};
    }
  }

  private writeStore(obj: Record<string, CacheEntry>): void {
    if (!this.isBrowser) {
      this.memCache = obj;
      return;
    }
    sessionStorage.setItem(TAB_CACHE_KEY, JSON.stringify(obj));
  }

  set<T>(id: string, data: T, ttlMs?: number): void {
    const store = this.readStore();
    store[id] = {
      data,
      savedAt: Date.now(),
      ttl: typeof ttlMs === 'number' ? ttlMs : null,
    };
    this.writeStore(store);
  }

  get<T>(id: string): T | null {
    const store = this.readStore();
    const entry = store[id] as CacheEntry<T> | undefined;
    if (!entry) return null;

    if (entry.ttl && Date.now() - entry.savedAt > entry.ttl) {
      // expired — remove it
      delete store[id];
      this.writeStore(store);
      return null;
    }
    return entry.data;
  }

  has(id: string): boolean {
    return this.get(id) !== null;
  }

  delete(id?: string): void {
    if (!id) {
      // clear all for this tab
      if (this.isBrowser) sessionStorage.removeItem(TAB_CACHE_KEY);
      this.memCache = {};
      return;
    }
    const store = this.readStore();
    delete store[id];
    this.writeStore(store);
  }

  keys(): string[] {
    return Object.keys(this.readStore());
  }
}
